class UploadService {
  static final ImagePicker _picker = ImagePicker();
  static Future<void> pickAndShow(BuildContext context, String pageName) async { try { final XFile? file = await _picker.pickImage(source: ImageSource.gallery); if (file != null) { ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$pageName: File Uploaded - ${file.name} - Ready - Rass Live Only - Zego ${ZegoConfig.appID} - Link: gofile.io/upload/${file.name} - Download Link Ready'))); } } catch (e) { ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$pageName Upload Error - $e - Fixing'))); } }
  static Future<void> pickVideoForVideoPage(BuildContext context) async { try { final XFile? video = await _picker.pickVideo(source: ImageSource.gallery); if (video != null) { ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('Video Editing Page: Video Uploaded - ${video.name} - Video Alag - Upload Link Ready - gofile.io/upload/${video.name} - Download Link - Rass Live Only'))); } else { await pickAndShow(context, "Video Editing"); } } catch (e) { await pickAndShow(context, "Video Editing"); } }
}

