class _LiveRoomState extends State<LiveRoom> { CameraController? ctrl; List<CameraDescription> allCams = []; bool isFront = true; bool isLive = false; @override void initState() { super.initState(); _startCamera(); } Future<void> _startCamera() async { try { allCams = await availableCameras(); if (allCams.isEmpty) return; CameraDescription selected = isFront ? allCams.firstWhere((c) => c.lensDirection == CameraLensDirection.front, orElse: () => allCams.first) : allCams.firstWhere((c) => c.lensDirection == CameraLensDirection.back, orElse: () => allCams.first); await ctrl?.dispose(); ctrl = CameraController(selected, ResolutionPreset.high, enableAudio: true); await ctrl!.initialize(); if (mounted) setState(() {}); } catch (e) {} } Future<void> _switchCamera() async { setState(() => isFront = !isFront); await _startCamera(); } @override void dispose() { ctrl?.dispose(); super.dispose(); } @override Widget build(BuildContext context) { return Scaffold(appBar: AppBar(backgroundColor: Colors.black, title: Text('${widget.roomName} - Rass Live Only - AppID ${ZegoConfig.appID}', style: const TextStyle(fontSize: 10)), leading: IconButton(icon: const Icon(Icons.arrow_back), onPressed: () => Navigator.pop(context))), body: Stack(children: [if (ctrl != null && ctrl!.value.isInitialized) SizedBox.expand(child: CameraPreview(ctrl!)) else Container(color: Colors.black, child: const Center(child: Text('LIVE - Camera ON', style: TextStyle(color: Colors.white38)))), Positioned(bottom: 0, left: 0, right: 0, child: Container(color: Colors.black54, padding: const EdgeInsets.all(8), child: Row(children: [ElevatedButton.icon(onPressed: ()=> UploadService.pickAndShow(context, "Live Room File"), icon: const Icon(Icons.upload), label: const Text('Upload File to Live')), const SizedBox(width: 8), ElevatedButton(style: ElevatedButton.styleFrom(backgroundColor: Colors.pink), onPressed: () => setState(() => isLive = !isLive), child: Text(isLive ? 'END' : 'Go LIVE'))]))),])); } }

